Return `Result` with a typed error so the failure must be handled and can carry a reason.
```rust
pub fn set(&mut self, key: String, value: String) -> Result<(), SetError> {
    if key.is_empty() { return Err(SetError::EmptyKey); }
    self.attributes.insert(key, value);
    Ok(())
}

pub fn checkout(&mut self, quantity: usize) -> Result<(), OutOfStock> {
    self.stock = self.stock.checked_sub(quantity).ok_or(OutOfStock)?;
    Ok(())
}
